async function api(path, options={}){
  const isWrite = options.method && options.method!=='GET';
  // Bound requests so interrupted WebViews cannot display an endless loader.
  const timeout=Number.isFinite(options.timeout)?options.timeout:15000;
  const controller=new AbortController();
  const id=setTimeout(()=>controller.abort(),timeout);
  const {timeout:unused,...fetchOptions}=options;
  const request={credentials:'same-origin',headers:isWrite?header:{},...fetchOptions,signal:controller.signal,cache:'no-store'};
  try{
    const response=await fetch('/api'+path,request);
    let payload;
    try{payload=await response.json()}catch{payload={detail:'Invalid server response.'}}
    if(!response.ok){const error=new Error(typeof payload.detail==='string'?payload.detail:'The operation failed.');error.status=response.status;throw error;}
    return payload;
  }catch(error){
    if(error.name==='AbortError')throw new Error('The server did not respond in time.');
    throw error;
  }finally{clearTimeout(id)}
}
