// v1.3.0  - private, one-time surprise notes bound to a single invitation.
async function maybeSurprise(stage,done=()=>{}){
  if(state.payload?.mode!=='invite' || state.payload?.read_only || !state.payload?.invite_code){done();return;}
  try{
    const response=await api('/surprises/next?stage='+encodeURIComponent(stage));
    const surprise=response.surprise;
    if(!surprise){done();return;}
    const img=surprise.media_id?`<img class="surprise-picture" alt="Özel sürpriz görseli" src="/api/surprise-media/${surprise.media_id}"/>`:'';
    const input=surprise.mode==='reply'?`<label class="surprise-reply-label" for="surprise-reply">${esc(PU('surpriseAnswer')||(surpriseUI[publicLanguage]||surpriseUI.en)[1])}</label><input id="surprise-reply" class="surprise-reply" maxlength="150" autocomplete="off" placeholder="♡"/>`:'';
    shell(`<div class="hero-wrap wide fade-enter"><div class="glass stacked-card surprise-card"><div class="surprise-mini">✦ ${esc(PU('surpriseTitle')||(surpriseUI[publicLanguage]||surpriseUI.en)[0])}</div>${img}<p class="surprise-text">${esc(surprise.body)}</p>${input}<div class="surprise-actions"><button id="surprise-next" class="primary-btn">${esc(surprise.button_label)}</button></div></div></div>`);
    $('#surprise-next').addEventListener('click',async()=>{
      const b=$('#surprise-next');b.disabled=true;
      try{await post('/surprises/'+surprise.id+'/respond',{answer:$('#surprise-reply')?.value||''}); await maybeSurprise(stage,done)}
      catch(e){toast(e.message);b.disabled=false}
    });
  }catch(e){toast(e.message);done()}
}
const DWM_MEDIA_LIMIT = 24 * 1024 * 1024;
const DWM_MEDIA_ACCEPT = 'image/*,.heic,.heif,.hif,.mpo,.avif';
async function uploadImageFile(file,path){
  if(!(file instanceof File)||file.size===0)return null;
  if(file.size>DWM_MEDIA_LIMIT)throw new Error('Files must be 24 MB or smaller.');
  // Real file content is validated by the backend. MIME/extension are only picker hints.
  return api(path,{method:'POST',timeout:60000,
    headers:{'X-DateWithMe-Request':'1','Content-Type':'application/octet-stream'},body:file});
}
async function uploadSurpriseFile(file){
  const uploaded=await uploadImageFile(file,'/admin/surprise-media/file');
  return uploaded?.id||null;
}
async function openProfileCrop(file){
  if(!file || file.size>DWM_MEDIA_LIMIT){toast('Photos must be 24 MB or smaller.');return}
  const host=$('#avatar-crop-host');if(!host)return;
  host.innerHTML='<div class="crop-dialog" role="dialog" aria-modal="true" aria-label="Profil fotoğrafını kırp"><div class="crop-panel"><h3>Fotoğrafı Kare Olarak Kırp</h3><p>Görseli kaydır, yakınlaştır ve 1:1 kırp.</p><canvas id="crop-canvas" width="320" height="320" aria-label="Kırpma önizlemesi"></canvas><label>Yakınlaştır <input type="range" id="crop-zoom" min="1" max="3" value="1" step=".05"></label><div class="button-row"><button class="mini-btn" id="crop-cancel" type="button">Cancel</button><button class="primary-btn" id="crop-save" type="button">Kırp ve Galeriye Ekle</button></div></div></div>';
  const canvas=$('#crop-canvas'),ctx=canvas.getContext('2d');let objectURL=null,img=new Image(),dx=0,dy=0,zoom=1,dragging=false,lastX=0,lastY=0;
  try{
    // Decode on the server first, so HEIC/MPO works even if Safari cannot preview the source.
    const r=await fetch('/api/admin/profile-photos/normalize',{method:'POST',credentials:'same-origin',headers:{'X-DateWithMe-Request':'1','Content-Type':'application/octet-stream'},body:file});
    if(!r.ok){const body=await r.json().catch(()=>({}));throw new Error(body.detail||'Görsel açılamadı.')}
    objectURL=URL.createObjectURL(await r.blob());
    await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=objectURL});
  }catch(e){host.innerHTML='';toast(e.message||'Fotoğraf okunamadı.');return}
  const draw=(size=320,target=canvas)=>{
    const c=target.getContext('2d'),z=Math.max(size/img.naturalWidth,size/img.naturalHeight)*zoom;
    const w=img.naturalWidth*z,h=img.naturalHeight*z;
    const mx=Math.max(0,(w-size)/2),my=Math.max(0,(h-size)/2);
    const ox=Math.max(-mx,Math.min(mx,dx*size/320)),oy=Math.max(-my,Math.min(my,dy*size/320));
    c.clearRect(0,0,size,size);c.drawImage(img,(size-w)/2+ox,(size-h)/2+oy,w,h);
  };draw();
  canvas.style.touchAction='none';
  canvas.addEventListener('pointerdown',e=>{dragging=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId)});
  canvas.addEventListener('pointermove',e=>{if(!dragging)return;dx+=e.clientX-lastX;dy+=e.clientY-lastY;lastX=e.clientX;lastY=e.clientY;draw()});
  canvas.addEventListener('pointerup',()=>dragging=false);canvas.addEventListener('pointercancel',()=>dragging=false);
  $('#crop-zoom').addEventListener('input',e=>{zoom=Number(e.target.value);draw()});
  const close=()=>{URL.revokeObjectURL(objectURL);host.innerHTML=''};
  $('#crop-cancel').onclick=close;
  $('#crop-save').onclick=async()=>{const btn=$('#crop-save');btn.disabled=true;try{
    const result=document.createElement('canvas');result.width=700;result.height=700;draw(700,result);
    const blob=await new Promise(resolve=>result.toBlob(resolve,'image/webp',.89));if(!blob)throw new Error('Kırpılan fotoğraf kaydedilemedi.');
    await api('/admin/profile-photos',{method:'POST',timeout:60000,headers:{'X-DateWithMe-Request':'1','Content-Type':'application/octet-stream'},body:blob});close();await refreshAdmin();toast('Fotoğraf galeriye eklendi 💕');
  }catch(e){toast(e.message);btn.disabled=false}};
}
function installMediaPreview(input){
  if(!input || input.dataset.previewReady)return;
  input.dataset.previewReady='1';
  input.addEventListener('change',()=>{
    let holder=input.closest('.surprise-file, .field, .form-actions');
    if(!holder)return;
    holder.querySelector('.media-local-preview')?.remove();
    const file=input.files?.[0];
    if(!file)return;
    const wrap=document.createElement('div');wrap.className='media-local-preview';
    const label=document.createElement('span');label.className='muted';
    label.textContent=`${file.name} · ${(file.size/1024/1024).toFixed(1)} MB`;
    wrap.append(label);
    const img=document.createElement('img');img.alt='Yüklenecek fotoğrafın önizlemesi';
    const url=URL.createObjectURL(file);
    img.onload=()=>URL.revokeObjectURL(url);
    img.onerror=()=>{URL.revokeObjectURL(url);img.remove();
      const note=document.createElement('span');note.className='muted';note.textContent='Bu biçimin önizlemesini tarayıcı göstermiyor; yükleme sonrası sunucu dönüştürecek.';wrap.append(note)};
    img.src=url;wrap.append(img);holder.append(wrap);
  });
}
