function stageIntro(){
  const p=state.payload || {};
  if(p.mode==='stranger'){
    const defaultLang=p.language||'en';
    if(!guestLanguageChoice || !localeNames[guestLanguageChoice])guestLanguageChoice=defaultLang;
    const picker=p.guest_language_picker?`<div class="guest-language"><label for="guest-language">${esc(PU('selectLanguage'))}</label><select id="guest-language" class="guest-language-select">${Object.entries(localeNames).map(([code,name])=>`<option value="${esc(code)}" ${code===guestLanguageChoice?'selected':''}>${esc(name)}</option>`).join('')}</select></div>`:'';
    shell(`<div class="hero-wrap"><div class="glass-icon">${heart}</div><article class="glass hero-card"><h1 class="hero-title" style="font-size:clamp(41px,5vw,70px)">${esc(T('stranger'))}</h1><p class="section-sub">${esc(T('strangerNote'))}</p><button class="primary-btn" id="guest-start" style="width:min(100%,300px)">${esc(T('guestButton'))}</button></article>${picker}</div>`);
    $('#guest-language')?.addEventListener('change',e=>{guestLanguageChoice=e.target.value;setLanguage(guestLanguageChoice);stageIntro()});
    $('#guest-start').addEventListener('click',async()=>{
      const button=$('#guest-start');button.disabled=true;
      try{
        const created=await post('/guest');
        const wanted=(guestLanguageChoice&&localeNames[guestLanguageChoice])?guestLanguageChoice:(p.language||'en');
        if(wanted && wanted!==(created.language||p.language||'en')) await post('/guest-language',{language:wanted});
        // Set-Cookie alone does not prove the browser saved a Secure session cookie.
        // In particular, browsers reject it on LAN HTTP when COOKIE_SECURE=1.
        const verified=await api('/bootstrap');
        if(!['guest','invite'].includes(verified.mode) || (created.mode==='guest'&&verified.mode!=='guest')){
          showSessionIssue();return;
        }
        state.payload=verified;visitorTranslations[verified.language]=verified.ui_translations||{};setLanguage(verified.language);state.step='intro';render();sendDevice();
      }catch(e){if(e.status===401)showSessionIssue();else toast(e.message)}
      finally{if(button.isConnected)button.disabled=false}
    });
    return;
  }
  if(p.mode==='revoked'||p.read_only)return stageRevoked();
  if(p.plan)return stageResult();
  const greeting=p.name?`${esc(T('hello'))} <strong>${esc(p.name)}</strong> 💕`:esc(T('anonymous'));
  const photo=p.photo_enabled?`<img class="invite-photo" src="${p.photo_id?'/api/invite-photo/'+p.photo_id:'/api/photo'}" alt="Profil fotoğrafı" />`:'';
  shell(`<div class="hero-wrap"><div class="glass-icon">${heart}</div><article class="glass hero-card">${photo}<div class="hero-eyebrow">${greeting}</div><h1 class="hero-title">${esc(T('inviteQuestion'))}</h1><div class="action-row" id="no-zone"><button id="yes" class="primary-btn btn-yes">${esc(T('yes'))}</button><button id="no" class="secondary-btn btn-no" tabindex="0">${esc(T('no'))}</button></div></article></div>`);
  $('#yes').addEventListener('click',()=>maybeSurprise('after_yes',()=>{state.step='activity';void saveProgress('activity');render()}));
  installRunaway();
}
function installRunaway(){
  const no=$('#no'),zone=$('#no-zone'), yes=$('#yes');
  if(!no||!zone||!yes)return;
  if(state.payload?.no_click_cancels){
    no.classList.add('decline-enabled');
    no.addEventListener('click',async()=>{
      if(!confirm(publicLanguage==='tr'?'Daveti reddetmek istiyor musun?': 'Decline this invitation?'))return;
      try{await post('/invites/decline');state.payload.mode='revoked';render()}catch(e){toast(e.message)}
    });
    return;
  }
  if(state.payload?.runaway_no===false)return;
  let last=0, moving=false;
  const mobile=()=>matchMedia('(pointer: coarse)').matches || innerWidth<650;
  const dist=(x,y,r)=>Math.hypot(Math.max(r.left-x,0,x-r.right),Math.max(r.top-y,0,y-r.bottom));
  const collision=(a,b,p=0)=> a.left<b.right+p && a.right>b.left-p && a.top<b.bottom+p && a.bottom>b.top-p;
  const rectFor=(x,y,w,h)=>({left:x,top:y,right:x+w,bottom:y+h});
  function moveAway(x,y){
    if(moving)return;
    moving=true;
    const current=no.getBoundingClientRect();
    const w=current.width,h=current.height;
    const margin=innerWidth<500?12:22;
    const topLimit=innerWidth<650?75:95;
    const lowerLimit=innerHeight-(innerWidth<650?62:72);
    const availableX=Math.max(margin,innerWidth-w-margin);
    const availableY=Math.max(topLimit,lowerLimit-h);
    const yesRect=yes.getBoundingClientRect();
    // Choose a location far from the cursor, previous position, and the YES button.
    // Desktop can use the entire viewport instead of the original tiny button row.
    let best=null, score=-Infinity;
    for(let i=0;i<90;i++){
      const a=Math.random();
      const nx=margin+a*(availableX-margin);
      const ny=topLimit+Math.random()*(availableY-topLimit);
      const next=rectFor(nx,ny,w,h);
      if(collision(next,yesRect,32))continue;
      const cursorDistance=dist(x,y,next);
      const travelled=Math.hypot(nx-current.left,ny-current.top);
      const minCursor=mobile()?85:118;
      const minTravel=mobile()?110:Math.min(165,innerWidth*.16);
      if(cursorDistance<minCursor || travelled<minTravel)continue;
      const value=Math.random()*350+Math.min(cursorDistance,380)*.24+Math.min(travelled,280)*.16; 
      if(value>score){score=value;best={x:nx,y:ny}}
    }
    // Very small viewports: still avoid covering the Yes button.
    if(!best){for(const [nx,ny] of [[availableX,topLimit],[margin,availableY],[availableX,availableY],[margin,topLimit]]){
      if(!collision(rectFor(nx,ny,w,h),yesRect,10)){best={x:nx,y:ny};break}
    }}
    if(best){
      if(!no.classList.contains('fleeing')){
        const initial=no.getBoundingClientRect();
        document.body.appendChild(no);no.classList.add('fleeing');
        no.style.left=Math.round(initial.left)+'px';no.style.top=Math.round(initial.top)+'px';
        requestAnimationFrame(()=>{if(no.isConnected){no.style.left=Math.round(best.x)+'px';no.style.top=Math.round(best.y)+'px'}});
      }else{
        no.style.left=Math.round(best.x)+'px';no.style.top=Math.round(best.y)+'px';
      }
    }
    moving=false;
  }
  function attempt(x,y){
    const now=performance.now();
    if(now-last<140)return;
    last=now;
    moveAway(x,y);
    // Keep network latency out of the interaction path.
    void post('/no-attempt').catch(()=>{});
  }
  function track(e){
    if(e.pointerType==='touch')return;
    const r=no.getBoundingClientRect();
    // React well before the pointer enters the button; pointerenter alone is too late.
    if(!mobile() && dist(e.clientX,e.clientY,yes.getBoundingClientRect())<60)return;
    if(dist(e.clientX,e.clientY,r)<(mobile()?100:95)) attempt(e.clientX,e.clientY);
  }
  function intercept(e){
    const r=no.getBoundingClientRect();
    if(dist(e.clientX,e.clientY,r)<3){
      e.preventDefault();e.stopImmediatePropagation();attempt(e.clientX,e.clientY);
    }
  }
  function keydown(e){
    if(document.activeElement===no && (e.key===' '||e.key==='Enter')){
      e.preventDefault(); e.stopImmediatePropagation(); attempt(innerWidth/2,innerHeight/2);
    }
  }
  function noClick(e){e.preventDefault();e.stopImmediatePropagation();attempt(e.clientX||innerWidth/2,e.clientY||innerHeight/2)}
  document.addEventListener('pointermove',track,{capture:true,passive:true});
  document.addEventListener('pointerdown',intercept,true);
  document.addEventListener('keydown',keydown,true);
  no.addEventListener('click',noClick,true);
  no.addEventListener('focus',()=>{no.blur();attempt(innerWidth/2,innerHeight/2)},{once:true});
  runawayCleanup=()=>{
    document.removeEventListener('pointermove',track,true);
    document.removeEventListener('pointerdown',intercept,true);
    document.removeEventListener('keydown',keydown,true);
    no.removeEventListener('click',noClick,true);
    if(!zone.contains(no))no.remove();
  };
}
async function saveProgress(stage,extra={}){
  try{await post('/progress',{stage,...extra})}
  catch(e){if(e.status===401)showSessionIssue();else toast(e.message)}
}
function stageActivity(){
  const content=`${stepDots(1)}<div class="eyebrow" style="text-align:center">${esc(T('activityEyebrow'))}</div><h1 class="section-title" style="text-align:center">${esc(T('activityTitle'))}</h1><div class="options">${catalog().map(x=>`<button class="option ${state.activity===x.id?'selected':''}" data-activity="${esc(x.id)}"><span class="option-emoji" aria-hidden="true">${esc(x.emoji)}</span><span class="option-label">${esc(x.label)}</span></button>`).join('')}</div><div class="bottom-actions"><button class="text-back" id="back-intro">${esc(T('back'))}</button><span class="muted">${esc(T('choose'))}</span></div>`;
  shell(card(content,true));
  $$('[data-activity]').forEach(button=>button.addEventListener('click',async()=>{state.activity=button.dataset.activity;await maybeSurprise('after_activity',()=>{state.step='schedule';saveProgress('schedule',{activity:state.activity});render();if(state.day)loadSlots()})}));
  $('#back-intro').addEventListener('click',()=>{state.step='intro';render()});
}
const $$=(q)=>[...document.querySelectorAll(q)];
function monthsAvailable(year,month){const t=new Date(today()+'T12:00:00');return new Date(year,month,1)<=new Date(t.getFullYear(),t.getMonth()+4,1)}
function dateGrid(){
  const y=state.month.getFullYear(),m=state.month.getMonth(),first=new Date(y,m,1);
  const offset=(first.getDay()+6)%7, count=new Date(y,m+1,0).getDate();
  const cells=Array.from({length:offset},()=>'<span class="day blank"></span>');
  const min=today(),max=new Date(new Date(min+'T12:00:00').getTime()+120*24*60*60*1000).toLocaleDateString('sv-SE');
  for(let i=1;i<=count;i++){
    const d=`${y}-${String(m+1).padStart(2,'0')}-${String(i).padStart(2,'0')}`;
    const disabled=d<min||d>max;
    cells.push(`<button class="day ${d===state.day?'selected':''} ${d===min?'today':''}" data-day="${d}" ${disabled?'disabled':''} aria-label="${esc(fmtDay(d,{dateStyle:'full'}))}" ${d===state.day?'aria-pressed="true"':''}>${i}</button>`);
  }
  return cells.join('');
}
function stageSchedule(){
  const content=`${stepDots(2)}<div class="eyebrow" style="text-align:center">${esc(T('whenEyebrow'))}</div><h1 class="section-title" style="text-align:center">${esc(T('whenTitle'))}</h1><p class="section-sub" style="text-align:center;margin-bottom:20px">${esc(T('whenSub'))}</p><div class="calendar-area"><div class="calendar-header"><button class="round-arrow" id="prev-month" aria-label="Önceki ay">‹</button><span class="month-title">${state.month.toLocaleDateString(publicLanguage,{month:'long',year:'numeric'})}</span><button class="round-arrow" id="next-month" aria-label="Sonraki ay">›</button></div><div class="week-header">${[0,1,2,3,4,5,6].map(i=>`<span>${new Date(2026,10,2+i).toLocaleDateString(publicLanguage,{weekday:'short'})}</span>`).join('')}</div><div class="day-grid">${dateGrid()}</div></div><div class="time-heading">${state.day?esc(fmtDay(state.day,{weekday:'long',day:'numeric',month:'long'}))+' · '+esc(T('time')):esc(T('firstDay'))}</div><div id="time-slots" class="slots">${slotsHTML()}</div><div class="bottom-actions"><button class="text-back" id="back-activity">${esc(T('back'))}</button><button class="primary-btn" id="book" ${!state.time?'disabled':''}>${esc(T('book'))}</button></div>`;
  shell(card(content));
  $('#prev-month').disabled=state.month.getFullYear()===new Date(today()+'T12:00:00').getFullYear() && state.month.getMonth()===new Date(today()+'T12:00:00').getMonth();
  $('#next-month').disabled=!monthsAvailable(state.month.getFullYear(),state.month.getMonth()+1);
  $('#prev-month').addEventListener('click',()=>{state.month=new Date(state.month.getFullYear(),state.month.getMonth()-1,1);render()});
  $('#next-month').addEventListener('click',()=>{state.month=new Date(state.month.getFullYear(),state.month.getMonth()+1,1);render()});
  $$('[data-day]').forEach(b=>b.addEventListener('click',()=>{state.day=b.dataset.day;state.time=null;state.slots=[];saveProgress('schedule',{day:state.day});render();loadSlots()}));
  installSlots();
  $('#back-activity').addEventListener('click',()=>{state.step='activity';render()});
  $('#book').addEventListener('click',async()=>{if(!state.time)return;await maybeSurprise('after_schedule',bookDate)});
}
async function bookDate(){
  try{const r=await post('/plans',{activity:state.activity,day:state.day,time:state.time});state.payload.plan=r.plan;state.step='complete';state.calendarOptions=false;resultSurpriseChecked=false;render();celebrate()}
  catch(e){if(e.status===401){showSessionIssue();return;}toast(e.message);render();await loadSlots()}
}
function slotsHTML(){
  if(!state.day)return `<div class="empty-hint" style="grid-column:1/-1">${esc(T('pickDate'))}</div>`;
  if(!state.slots.length)return `<div class="empty-hint" style="grid-column:1/-1">${esc(T('loadingSlots'))}</div>`;
  if(!state.slots.some(x=>x.available))return `<div class="empty-hint" style="grid-column:1/-1">${esc(T('busy'))}</div>`;
  return state.slots.map(s=>`<button data-time="${s.time}" class="slot ${state.time===s.time?'selected':''}" ${!s.available?'disabled':''}>${s.time}</button>`).join('');
}
function installSlots(){
  $$('[data-time]').forEach(b=>b.addEventListener('click',()=>{state.time=b.dataset.time;saveProgress('schedule',{time:state.time});render()}));
}
async function loadSlots(){
  if(!state.day)return;
  const requested=state.day;
  try{const data=await api('/availability?day='+encodeURIComponent(requested));if(state.day!==requested)return;state.slots=data.slots;render()}
  catch(e){toast(e.message);state.slots=[];const slots=$('#time-slots');if(slots)slots.innerHTML='<div class="empty-hint">Saatler alınamadı.</div>'}
}
function celebrate(){
  if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  const fx=$('#effects');if(!fx)return;
  const glyphs=['💕','💖','✨','💜','✦','💗','♡'];
  for(let i=0;i<42;i++){const el=document.createElement('span');el.className='particle';el.textContent=glyphs[Math.floor(Math.random()*glyphs.length)];el.style.setProperty('--tx',`${Math.round((Math.random()-.5)*window.innerWidth*.95)}px`);el.style.setProperty('--ty',`${Math.round((Math.random()-.5)*window.innerHeight*.95)}px`);el.style.setProperty('--rot',`${Math.round(Math.random()*360)}deg`);el.style.animationDelay=(Math.random()*.24)+'s';fx.append(el);setTimeout(()=>el.remove(),2250)}
}
function details(plan){
  return `<div class="details"><div class="detail-row"><small>${esc(T('activity'))}</small><strong>${esc(plan.activity_label)}</strong></div><div class="detail-row"><small>${esc(T('date'))}</small><strong>${esc(fmtDay(plan.day,{weekday:'long',day:'numeric',month:'long',year:'numeric'}))}</strong></div><div class="detail-row"><small>${esc(T('time'))}</small><strong>${esc(plan.time)}</strong></div></div>`;
}
function calendarOptions(plan){
  const a=new Date(plan.start_utc),b=new Date(plan.end_utc);
  const gfmt=x=>x.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');
  const title='Date with '+ownerName+' 💕',description=plan.activity_label;
  const google='https://calendar.google.com/calendar/render?action=TEMPLATE&text='+encodeURIComponent(title)+'&dates='+gfmt(a)+'/'+gfmt(b)+'&details='+encodeURIComponent(description);
  const outlook='https://outlook.live.com/calendar/0/deeplink/compose?path=%2Fcalendar%2Faction%2Fcompose&rru=addevent&subject='+encodeURIComponent(title)+'&startdt='+encodeURIComponent(a.toISOString())+'&enddt='+encodeURIComponent(b.toISOString())+'&body='+encodeURIComponent(description);
  const ics='/api/calendar.ics'+(state.code?'?code='+encodeURIComponent(state.code):'');
  return `<div class="calendar-choice"><a class="cal-link" href="${ics}">${serviceIcon('apple')}<span class="cal-name">${esc(PU('appleCalendar'))}</span>${iconSVG('arrow','cal-arrow')}</a><a class="cal-link" target="_blank" rel="noopener noreferrer" href="${google}">${serviceIcon('google')}<span class="cal-name">${esc(PU('googleCalendar'))}</span>${iconSVG('arrow','cal-arrow')}</a><a class="cal-link" target="_blank" rel="noopener noreferrer" href="${outlook}">${serviceIcon('outlook')}<span class="cal-name">${esc(PU('outlookCalendar'))}</span>${iconSVG('arrow','cal-arrow')}</a></div>`;
}
async function loadAfterDateNotes(){
  const id=(crypto.randomUUID?.()||`${Date.now()}-${Math.random()}`).replaceAll('-','');
  try{
    const result=await post('/after-date/view',{page_load_id:id});
    afterDateNotes=result.notes||[];
  }catch(e){afterDateNotes=[];console.warn('after-date note:',e?.message)}
  afterDateNoteIndex=0;
  if(afterDateNotes.length){showAfterDateNote();}else{afterDateVisible=false;stageResult();}
}
function showAfterDateNote(){
  const n=afterDateNotes?.[afterDateNoteIndex];
  if(!n){afterDateVisible=false;stageResult();return;}
  afterDateVisible=true;
  const media=n.media_id?`<img class="surprise-picture" src="/api/surprise-media/${n.media_id}" alt="Özel anı görseli"/>`:'';
  const input=n.mode==='reply'?`<label class="surprise-reply-label" for="after-date-reply">${esc(PU('surpriseAnswer')||(surpriseUI[publicLanguage]||surpriseUI.en)[1])}</label><input id="after-date-reply" class="surprise-reply" maxlength="150" autocomplete="off" />`:'';
  shell(`<div class="hero-wrap wide fade-enter"><div class="glass stacked-card surprise-card"><div class="surprise-mini">♡ ${esc(PU('postDateNote'))}</div>${media}<p class="surprise-text">${esc(n.body)}</p>${input}<div class="surprise-actions"><button class="primary-btn" id="after-date-next">${esc(n.button_label||T('back'))}</button></div></div></div>`);
  $('#after-date-next').addEventListener('click',async()=>{
    const b=$('#after-date-next');b.disabled=true;
    try{if(n.mode==='reply')await post('/surprises/'+n.id+'/respond',{answer:$('#after-date-reply')?.value||''})}
    catch(e){toast(e.message)}
    afterDateNoteIndex++;showAfterDateNote();
  });
}
function stageResult(){
  const p=state.payload, plan=p.plan;
  if(plan.past && plan.status==='planned' && p.mode==='invite' && !afterDateChecked){
    afterDateChecked=true;
    shell(card(`<div class="eyebrow" style="text-align:center">♡</div><h1 class="section-title" style="text-align:center">${esc(T('past'))}</h1>`));
    void loadAfterDateNotes();return;
  }
  if(afterDateVisible)return;
  const name=p.name?`${esc(T('hello'))} <strong>${esc(p.name)}</strong> ${plan.status==='cancelled'?'😏':'💕'}`:esc(T('anonymous'));
  let central='';
  if(plan.status==='cancelled'){
    central=`<div class="status-icon red-glow">💔</div><h1 class="section-title status-danger">${esc(T('cancelled'))}</h1><p class="status-note">${esc(plan.cancellation_message==='The invitation has been cancelled by the host.'?T('cancelDefault'):plan.cancellation_message)}</p>${details(plan)}`;
    if(!state.loggedView){state.loggedView=true;const id=(crypto.randomUUID?.()||`${Date.now()}-${Math.random()}`).replaceAll('-','');post('/cancel-view',{page_load_id:id,code:state.code||null}).catch(()=>{});}
  }else if(plan.past){central=`<div class="status-icon">🕰️</div><h1 class="section-title">${esc(T('past'))}</h1><p class="section-sub">${esc(T('pastSub'))}</p>${details(plan)}`}
  else{central=`<div class="success-heart" aria-hidden="true">💗</div><h1 class="section-title">${esc(T('planned'))}</h1>${details(plan)}${state.calendarOptions?calendarOptions(plan):`<button class="primary-btn" id="show-cal">${iconSVG('calendar','button-icon')} ${esc(T('addCalendar'))}</button>`}${state.payload.visitor_notifications?`<div class="visitor-notice-opt"><button class="mini-btn" id="visitor-push-on">${esc((OPTIONAL_PUSH_COPY[publicLanguage]||OPTIONAL_PUSH_COPY.tr)[0])}</button><button class="mini-btn" id="visitor-push-off">${esc((OPTIONAL_PUSH_COPY[publicLanguage]||OPTIONAL_PUSH_COPY.tr)[1])}</button></div>`:''}`}
  shell(card(`<div class="hero-eyebrow" style="text-align:center;margin-bottom:28px">${name}</div><div style="text-align:center">${central}</div>`));
  if(plan.status==='planned'&&!plan.past&&!resultSurpriseChecked){resultSurpriseChecked=true;void maybeSurprise('result',()=>{stageResult()});}
  $('#show-cal')?.addEventListener('click',()=>{state.calendarOptions=true;render()});
  $('#visitor-push-on')?.addEventListener('click',()=>requestPushPermission('visitor'));
  $('#visitor-push-off')?.addEventListener('click',()=>disablePush('visitor'));
}
function stageRevoked(){const name=state.payload?.name; shell(card(`<div class="status-icon" style="text-align:center">💌</div><div class="hero-eyebrow" style="text-align:center">${name?esc(T('hello'))+' '+esc(name)+' 💕':''}</div><h1 class="section-title" style="text-align:center;margin-top:22px">${esc(T('revoked'))}</h1><p class="section-sub" style="text-align:center">${esc(T('revokedSub'))}</p>`))}
function privacy(){
  const copy=PRIVACY_COPY[publicLanguage]||PRIVACY_COPY.en;
  shell(card(`<div class="eyebrow">${esc(T('privacy'))}</div><h1 class="section-title">${esc(T('privacy'))} 💜</h1><div class="privacy-content">${copy.map(line=>`<p>${esc(line.replaceAll('{owner}',ownerName))}</p>`).join('')}<p><a href="/">← ${esc(T('goHome'))}</a></p></div>`,true));
}
function render(){updateDocumentBranding();if(location.pathname==='/privacy')return privacy();if(location.pathname==='/panel')return renderAdmin();if(!state.payload)return;
  if(state.payload.plan)return stageResult();
  if(state.step==='activity')return stageActivity();
  if(state.step==='schedule')return stageSchedule();
  return stageIntro();
}

