const adminEnglishReverse=Object.fromEntries(Object.entries(adminEnglishFallbacks).map(([original,english])=>[english,original]));
function translateAdminNodes(){
 const code=admin?.settings?.admin_language||'en';
 const table={...(code==='tr'?{}:panelDictionary.en),...(panelDictionary[code]||{}),...(admin?.ui_overrides?.admin?.[code]||{})};
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
 while(walker.nextNode()){
   const node=walker.currentNode, parent=node.parentElement;
   if(!parent||['SCRIPT','STYLE','INPUT','TEXTAREA','OPTION','CODE'].includes(parent.tagName))continue;
   const v=node.textContent,trim=v.trim();
   const original=adminEnglishReverse[trim]||trim;
   const translated=table[original]||table[trim]||(code==='tr'?original:adminEnglishFallbacks[trim]||trim);
   if(translated!==trim)node.textContent=v.replace(trim,translated);
 }
}

function renderAdmin(){
  updateDocumentBranding();
  if(!admin){
    root.innerHTML=`<div class="panel-login-wrap"><div class="glass panel-login"><a href="/" class="brand">${brand}</a><h1>Admin dashboard</h1><p>Sign in to manage your invitations.</p><form id="login-form"><div class="field"><label for="admin-pwd">Administrator password</label><input id="admin-pwd" type="password" autocomplete="current-password" placeholder="Enter your password" required autofocus /></div><button class="primary-btn">Sign in ↗</button></form><p class="muted" style="margin-top:25px"><a href="/">← Return to site</a></p></div></div>`;
    $('#login-form').addEventListener('submit',async e=>{e.preventDefault();const b=$('button',e.target);b.disabled=true;try{await post('/admin/login',{password:$('#admin-pwd').value});admin=await api('/admin/state');applyPublicConfig({owner_name:admin.settings.owner_name,timezone:admin.settings.app_timezone});renderAdmin()}catch(err){toast(err.message)}finally{b.disabled=false}});return;
  }
  root.innerHTML=`<div class="admin-shell"><aside class="admin-side"><div class="admin-brand-wrap"><a href="/" class="brand">${brand}</a><span class="admin-brand-subtitle">Admin dashboard</span></div><button class="mini-btn mobile-menu" id="menu-toggle">☰ Menu</button><nav class="admin-nav ${mobileNav?'open':''}">${tabs.map(([id,ic,label])=>`<button class="nav-item ${id===adminTab?'active':''}" data-tab="${id}">${iconSVG(ic,'nav-icon')}${id==='support'?esc(supportI18n()[0]):label}${id==='notifications'&&admin.unread_notifications?`<span class="notice-dot">${Math.min(99,admin.unread_notifications)}</span>`:''}</button>`).join('')}</nav><button class="nav-item admin-logout" id="logout" aria-label="Sign Out">${iconSVG('logout','nav-icon')}<span class="logout-label">Sign Out</span></button></aside><main class="admin-content"><div class="admin-top"><div><h1>${adminTab==='support'?esc(supportI18n()[0]):adminTitles[adminTab]}</h1><p>${adminTab==='support'?'Orictux open source project':'Everything is under control. 💜'}</p></div><span class="small-tag">Private Dashboard</span></div><div id="panel-content">${adminContent()}</div></main></div>`;
  $$('[data-tab]').forEach(btn=>btn.addEventListener('click',()=>{adminTab=btn.dataset.tab;mobileNav=false;renderAdmin()}));
  $('#menu-toggle')?.addEventListener('click',()=>{mobileNav=!mobileNav;$('.admin-nav').classList.toggle('open',mobileNav)});
  $('#logout').addEventListener('click',async()=>{try{await disablePush('admin')}catch{}await post('/admin/logout');admin=null;clearInterval(notificationPoll);notificationPoll=null;renderAdmin()});
  attachAdminActions();
  translateAdminNodes();
  beginNotificationPoll();
}
function adminContent(){switch(adminTab){case'notifications':return adminNotifications();case'overview':return adminOverview();case'invites':return adminInvites();case'decks':return adminDecks();case'surprises':return adminSurprises();case'localization':return adminLocalization();case'plans':return adminPlans();case'calendar':return adminCalendar();case'visits':return adminVisits();case'settings':return adminSettings();case'support':return adminSupport();default:return ''}}

function notificationGlyph(kind){return ({invite_opened:'💌',planned:'💕',cancelled:'💔',reactivated:'✨'})[kind]||'🔔'}
function adminNotifications(){
 const notifications=admin.notifications||[];
 const unread=admin.unread_notifications||0;
 const controls=`<div class="notice-buttons"><button class="mini-btn" id="notice-all-read">Mark All as Read</button><button class="mini-btn danger" id="notice-clear">Delete Read Notifications</button></div>`;
 const list=notifications.length?notifications.map(n=>`<div class="notice-row ${n.read_at?'':'notice-unread'}"><span class="notice-icon">${notificationGlyph(n.kind)}</span><div class="notice-copy"><strong>${esc(n.title)}</strong><div>${esc(n.body)}</div><small>${esc(readableTs(n.created_at))}</small></div>${n.read_at?'<span class="notice-read">Read</span>':`<button class="mini-btn" data-notice-read="${n.id}">Read</button>`}</div>`).join(''):empty('Henüz bildirim yok. New Invitationler ve tamamlanan planlar burada görünecek.');
 const pushSupport=('serviceWorker' in navigator)&&('PushManager' in window)&&('Notification' in window)&&window.isSecureContext;
 const pushHint=pushSupport?'Once you grant permission, this device can receive notifications even when the browser is closed.':'Web Push is not supported in this browser. On iPhone, add the site to the Home Screen from Safari.';
 return `<div class="stats"><div class="stat"><span>Unread notifications</span><strong>${unread}</strong></div><div class="stat"><span>Recent notifications</span><strong>${notifications.length}</strong></div></div>
 ${panelCard('Device Notifications',`<p>${pushHint}</p><div class="notice-buttons"><button id="admin-push-on" class="primary-btn" ${pushSupport?'':'disabled'}>🔔 Enable Notifications on This Device</button><button id="admin-push-off" class="mini-btn">Disable on This Device</button><button id="admin-push-all-off" class="mini-btn danger">Remove All Devices</button></div><p class="muted">Permission is requested only when you click this button. Invitees are never prompted by this setting.</p>`)}
 ${panelCard(`Notification History · ${unread} unread`,controls+`<div class="notice-list">${list}</div>`)}`;
}
function beginNotificationPoll(){
 if(notificationPoll || !admin)return;
 notificationPoll=setInterval(async()=>{
   if(!admin || document.hidden)return;
   try{
     const payload=await api('/admin/notifications');
     const prev=admin.unread_notifications;
     const oldId=admin.notifications?.[0]?.id;
     admin.notifications=payload.notifications;
     admin.unread_notifications=payload.unread;
     const badge=$('.notice-dot');
     if(badge)badge.textContent=String(Math.min(99,payload.unread));
     if(adminTab==='notifications' && (prev!==payload.unread || oldId!==payload.notifications?.[0]?.id))renderAdmin();
   }catch{}
 },15000);
}
async function requestPushPermission(audience='admin'){
 if(!('serviceWorker' in navigator) || !('PushManager' in window) || !('Notification' in window) || !window.isSecureContext){toast('Notifications bu ortamda desteklenmiyor.');return}
 try{
   // Request permission directly from the click gesture, BEFORE network/worker awaits.
   const permission=await Notification.requestPermission();
   if(permission!=='granted'){toast('Bildirim izni verilmedi.');return}
   const registration=await navigator.serviceWorker.register('/service-worker.js',{scope:'/'});
   const info=await api('/push/public-key');
   const convert=value=>{
     const pad='='.repeat((4-value.length%4)%4);
     const raw=atob((value+pad).replace(/-/g,'+').replace(/_/g,'/'));
     return Uint8Array.from(raw,c=>c.charCodeAt(0));
   };
   let sub=await registration.pushManager.getSubscription();
   if(!sub)sub=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:convert(info.public_key)});
   await post(audience==='admin'?'/admin/push/subscribe':'/visitor/push/subscribe',{subscription:sub.toJSON()});
   toast('Notifications bu cihazda etkin! 💜');
 }catch(e){toast(e.message||'Unable to enable notifications.')}
}
async function disablePush(audience='admin'){
 try{
   const reg=await navigator.serviceWorker.getRegistration('/');
   const subscription=reg&&await reg.pushManager.getSubscription();
   if(subscription)await subscription.unsubscribe();
   await post(audience==='admin'?'/admin/push/unsubscribe':'/visitor/push/unsubscribe');
   toast('Notifications have been disabled on this device.');
 }catch(e){toast(e.message)}
}

function adminOverview(){
  const active=admin.invites.filter(i=>!i.revoked&&!admin.plans.some(p=>p.invite_id===i.id)).length;
  const scheduled=admin.plans.filter(p=>p.status==='planned' && !p.past && p.invite_id).length;
  const cancelled=admin.plans.filter(p=>p.status==='cancelled').length;
  return `<div class="stats"><div class="stat"><span>Open Invitations</span><strong>${active}</strong></div><div class="stat"><span>Upcoming Dates</span><strong>${scheduled}</strong></div><div class="stat"><span>Cancelled Dates</span><strong>${cancelled}</strong></div><div class="stat"><span>Guest Records</span><strong>${admin.plans.filter(p=>!p.invite_id).length}</strong></div></div><div class="panel-grid">${panelCard('Upcoming Dates',admin.plans.filter(p=>p.status==='planned'&&!p.past).slice(0,5).map(p=>`<div class="data-row"><div class="data-row-main"><strong>${esc(p.person_name||'Anonymous visitor')}</strong><small>${esc(p.activity_label)} · ${esc(shortDay(p.day))} ${esc(p.time)}</small></div>${statusBadge(p.status)}</div>`).join('')||empty())}${panelCard('Recent Activity',admin.events.slice(0,7).map(e=>`<div class="data-row"><div class="data-row-main"><strong>${esc(({invitation:'New Invitation',planned:'Date scheduled',cancelled:'Date cancelled',reactivated:'Date restored',reset:'Invitation reset',bulk_delete:'Records removed',invitation_deleted:'Invitation deleted'}[e.kind]||e.kind))}</strong><small>${esc(e.subject)} · ${esc(readableTs(e.created_at))}</small></div></div>`).join('')||empty())}</div>`;
}
function invitationUrl(code){return (admin?.settings?.public_base_url||location.origin).replace(/\/$/,'')+'/date?'+encodeURIComponent(code)}
function adminInvites(){
  const editInvite=(admin.invites||[]).find(i=>i.id===editingInviteId&&i.editable)||null;
  const editSurprises=editInvite?(admin.surprises||[]).filter(s=>s.invite_id===editInvite.id):[];
  const persons=admin.people.filter(p=>!p.archived).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');
  const create=panelCard(editInvite?'Edit Invitation':'Create a new invitation',`<form id="invite-form"><div class="form-grid"><div class="field"><label>Invitee name</label><input name="name" maxlength="60" value="${esc(editInvite?.person_name||'')}" placeholder="Example: Alex" /></div><div class="field"><label>Or select an existing person</label><select name="person_id"><option value="">Create a new person</option>${admin.people.filter(p=>!p.archived).map(p=>`<option value="${p.id}" ${editInvite?.person_id===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><button type="button" class="mini-btn" id="manage-people" aria-expanded="${peopleManagerOpen}">♧ Manage Saved People</button></div><div class="field"><label>Invitation code length</label><select name="code_length" ${editInvite?'disabled':''}><option value="16">16 characters (recommended)</option><option value="20">20 characters</option><option value="24">24 characters</option><option value="5">5 characters (less secure)</option><option value="4">4 characters (less secure)</option></select></div><div class="field"><label>Activity deck</label><select name="deck_id">${(admin.decks||[]).filter(d=>!d.archived&&d.cards.length).map(d=>`<option value="${d.id}" ${editInvite?.deck_id===d.id?'selected':''}>${esc(d.name)} · ${d.cards.length} cards</option>`).join('')}</select></div><div class="field"><label>Invitation language</label><select name="language">${Object.entries(admin.languages||localeNames).map(([code,name])=>`<option value="${esc(code)}" ${code===(editInvite?.language||admin.settings.guest_language||'en')?'selected':''}>${esc(name)}</option>`).join('')}</select></div><div class="field"><label>Profile photo (optional)</label><select name="photo_id"><option value="">No profile photo</option>${(admin.profile_photos||[]).map(photo=>`<option value="${photo.id}" ${editInvite?.photo_id===photo.id?'selected':''}>${esc(photo.name)}</option>`).join('')}</select><button class="mini-btn" type="button" id="goto-profiles">＋ Profile Photo Gallery</button></div></div><div class="surprise-creator"><label class="switch"><input id="surprise-enabled" type="checkbox" ${editSurprises.length?'checked':''}> Add a personal surprise (off by default)</label><div id="surprise-configs" ${editSurprises.length?'':'hidden'}>${editSurprises.map(s=>surpriseFormRow(s)).join('')}</div><button class="mini-btn" type="button" id="add-surprise-row" ${editSurprises.length?'':'hidden'}>＋ Add another surprise message</button></div><div class="form-actions"><button type="button" class="mini-btn" id="preview-new-invite">◉ Preview as Invitee (Test)</button>${editInvite?'<button type="button" class="mini-btn" id="cancel-edit-invite">Cancel Editing</button>':''}<button class="primary-btn">${editInvite?'✓ Update Invitation':'✦ Create Invitation Link'}</button></div><div id="created-link">${lastCreated?createdLinkHTML(lastCreated):''}</div></form>`);
  const rows=admin.invites.map(i=>{
    const plan=admin.plans.find(p=>p.invite_id===i.id),status=plan?statusBadge(plan.status):statusBadge(i.revoked?'revoked':'pending');
    return `<div class="data-row"><div class="data-row-main"><strong>${esc(i.person_name)} <span class="muted">· Date #${String(i.sequence).padStart(3,'0')}</span></strong><small><span class="code">${esc(invitationUrl(i.code))}</span></small><div>${status}<small class="deck-info">${esc((admin.decks||[]).find(d=>d.id===i.deck_id)?.name||'Classic')} · ${esc(localeNames[i.language]||i.language||'Turkish')}</small></div></div><div class="button-row"><button class="mini-btn" data-preview-invite="${i.id}">Preview</button>${i.editable?`<button class="mini-btn" data-edit-invite="${i.id}">Edit</button>`:'<span class="invite-locked" title="This invitation has already been opened and cannot be edited">🔒 Opened</span>'}<button class="mini-btn" data-copy="${esc(invitationUrl(i.code))}">Copy</button><button class="mini-btn" data-reset="${i.id}">Reset</button><button class="mini-btn danger" data-delete-invite="${i.id}">Delete</button></div></div>`
  }).join('');
  const existing=(admin.surprises||[]).map(s=>`<div class="data-row"><div class="data-row-main"><strong>${esc(s.person_name)} · ${esc(SURPRISE_STAGES.find(x=>x[0]===s.stage)?.[1]||s.stage)}</strong><small>${esc(s.body)}${s.response_text!==null&&s.response_text!==undefined?` · ✉ ${esc(s.response_text||'No response')}`:''}${s.completed_at?' · Viewed / completed':''}</small></div><button class="mini-btn danger" data-delete-surprise="${s.id}">Delete</button></div>`).join('');
  const peopleRows=(admin.people||[]).map(person=>`<div class="person-manager-entry"><form class="person-name-form" data-person-form="${person.id}"><label for="person-name-${person.id}" class="smaller">${person.archived?'Archived person':'Saved person'} · ${person.invite_count} davet · ${person.plan_count} date</label><div class="person-name-line"><input id="person-name-${person.id}" name="name" maxlength="60" value="${esc(person.name)}" required aria-label="Person name"><button class="mini-btn" type="submit">Save</button></div></form><div class="person-actions">${person.archived?`<button class="mini-btn" type="button" data-restore-person="${person.id}">Restore</button>`:`<button class="mini-btn" type="button" data-archive-person="${person.id}">Remove from List</button>`}<button class="mini-btn danger" type="button" data-delete-person="${person.id}">Delete Permanently</button></div></div>`).join('');
  const peopleManage=peopleManagerOpen?panelCard('Saved People',`<div id="people-list"><p class="muted">Rename, archive or permanently delete a saved person. Archiving keeps existing invitations intact.</p><div class="person-manager-list">${peopleRows||empty('No saved people yet.')}</div></div>`):'';
  const timelineCards=admin.settings.timeline_enabled==='1'?panelCard('Invitation Timelines',`<p>Shows actual events only. Preview tests are not recorded here.</p>${(admin.invites||[]).map(i=>`<details class="timeline-entry"><summary>${esc(i.person_name)} · Date #${String(i.sequence).padStart(3,'0')}</summary><div class="timeline-events">${(admin.timeline?.[String(i.id)]||[]).map(e=>`<div class="timeline-event"><span>✦ ${esc(e.label)}</span><small>${esc(readableTs(e.when))}</small></div>`).join('')||empty()}</div></details>`).join('')||empty()}`):'';
  return create+peopleManage+panelCard('Sent Invitations',`<div class="data-list">${rows||empty('No invitations created yet.')}</div>`)+timelineCards+panelCard('Personal Surprises',`<div class="data-list">${existing||empty('No personal surprises yet.')}</div>`);
}
