// Admin-only preview: zero API mutations, zero cookie changes, zero events.
function closeInvitePreview(){
  document.getElementById('dwm-preview')?.remove();
  for(const u of previewObjectUrls)URL.revokeObjectURL(u);
  previewObjectUrls=[];previewState=null;
}
function openInvitePreview(inviteId=null){
  if(!admin)return;
  closeInvitePreview();
  let invite=inviteId?admin.invites.find(x=>x.id===inviteId):null;
  const f=document.getElementById('invite-form');
  const form=f?new FormData(f):null;
  const deckId=invite?Number(invite.deck_id):Number(form?.get('deck_id')||1);
  const lang=invite?.language||String(form?.get('language')||'en');
  const deck=(admin.decks||[]).find(x=>x.id===deckId)||admin.decks?.[0];
  const name=invite?.person_name||admin.people.find(x=>x.id===Number(form?.get('person_id')))?.name||String(form?.get('name')||'Example Davetli').trim();
  const specs=invite?(admin.surprises||[]).filter(s=>s.invite_id===invite.id).map(s=>({...s})) : [];
  if(!invite && document.getElementById('surprise-enabled')?.checked){
    for(const row of document.querySelectorAll('[data-surprise-row]')){
      const g=n=>row.querySelector(`[name="${n}"]`)?.value||'';
      let note={stage:g('surprise_stage'),body:g('surprise_body'),mode:g('surprise_mode'),button_label:g('surprise_button')||'Continue 💕'};
      const template=(admin.surprise_templates||[]).find(t=>t.id===Number(g('surprise_template')));
      if(template)note={...template,stage:note.stage};
      const file=row.querySelector('[name="surprise_file"]')?.files?.[0];
      if(file){note.media_url=URL.createObjectURL(file);previewObjectUrls.push(note.media_url)}
      if(note.body||note.media_url)specs.push(note);
    }
  }
  const phases=['before_intro','intro','after_yes','activity','after_activity','schedule','after_schedule','result','after_date'];
  const steps=[];
  for(const phase of phases){
    if(['intro','activity','schedule','result'].includes(phase))steps.push({kind:phase});
    if(phase==='after_date')steps.push({kind:'past'});
    for(const spec of specs.filter(s=>s.stage===phase))steps.push({kind:'surprise',spec});
  }
  previewState={name,lang,deck,steps,photoId:invite?.photo_id||Number(form?.get('photo_id'))||null,position:0,device:'mobile',activity:deck?.cards?.[0],day:today(),time:'19:00'};
  const el=document.createElement('div');el.id='dwm-preview';el.className='dwm-preview-modal';el.setAttribute('role','dialog');el.setAttribute('aria-modal','true');el.setAttribute('aria-label','Invitation test preview');document.body.appendChild(el);
  renderInvitePreview();
}
function renderInvitePreview(){
  const p=previewState,el=document.getElementById('dwm-preview');if(!p||!el)return;
  const phase=p.steps[p.position]||{kind:'past'};
  const txt=k=>phrase(p.lang,k);
  const c=(title,body)=>`<div class="glass preview-glass"><div class="preview-heart">♡</div><div class="hero-eyebrow">${esc(title)}</div>${body}</div>`;
  let content='';
  if(phase.kind==='intro')content=c(`${txt('hello')} ${p.name} 💕`,`${p.photoId?`<img class="invite-photo" src="/api/admin/profile-photos/${p.photoId}" alt="Profile photo" />`:''}<h2 class="preview-heading">${esc(txt('inviteQuestion'))}</h2><div class="preview-choices"><button type="button" id="preview-yes" class="primary-btn">${esc(txt('yes'))}</button><button type="button" id="preview-no" class="secondary-btn">${esc(txt('no'))}</button></div>`);
  else if(phase.kind==='activity')content=c(txt('activityEyebrow'),`<h2 class="preview-heading">${esc(txt('activityTitle'))}</h2><div class="preview-options">${(p.deck?.cards||[]).map(card=>`<button type="button" data-preview-activity="${esc(card.id)}" class="option ${p.activity?.id===card.id?'selected':''}"><span class="option-emoji">${esc(card.emoji)}</span><span class="option-label">${esc(card.translations?.[p.lang]||card.label)}</span></button>`).join('')}</div>`);
  else if(phase.kind==='schedule')content=c(txt('whenEyebrow'),`<h2 class="preview-heading">${esc(txt('whenTitle'))}</h2><p class="section-sub">${esc(txt('whenSub'))}</p><div class="preview-fields"><label>${esc(txt('date'))}<input id="preview-day" type="date" value="${esc(p.day)}"/></label><label>${esc(txt('time'))}<select id="preview-time">${['16:00','17:00','18:00','19:00','20:00','21:00'].map(t=>`<option ${p.time===t?'selected':''}>${t}</option>`).join('')}</select></label></div><p class="muted">Simulation only. Actual availability is not checked.</p><button type="button" id="preview-book" class="primary-btn">${esc(txt('book'))}</button>`);
  else if(phase.kind==='result')content=c(`${txt('hello')} ${p.name} 💕`,`<div class="preview-success">💕</div><h2 class="preview-heading">${esc(txt('planned'))}</h2><div class="details"><div class="detail-row"><small>${esc(txt('activity'))}</small><strong>${esc(p.activity?.translations?.[p.lang]||p.activity?.label||'-')}</strong></div><div class="detail-row"><small>${esc(txt('date'))}</small><strong>${esc(p.day)}</strong></div><div class="detail-row"><small>${esc(txt('time'))}</small><strong>${esc(p.time)}</strong></div></div>`);
  else if(phase.kind==='past')content=c(`${txt('hello')} ${p.name} 💕`,`<div class="preview-success">🕰️</div><h2 class="preview-heading">${esc(txt('past'))}</h2><p class="section-sub">${esc(txt('pastSub'))}</p>`);
  else if(phase.kind==='surprise'){
    const n=phase.spec;
    const image=n.media_url|| (n.media_id?`/api/surprise-media/${n.media_id}`:null);
    const media=image?`<img class="surprise-picture" alt="Surprise media preview" src="${esc(image)}"/>`:'';
    content=c(`${txt('hello')} ${p.name} 💕`,`<div class="surprise-mini">✦ ${esc(visitorTranslations?.[p.lang]?.surpriseTitle||(surpriseUI[p.lang]||surpriseUI.en)[0])}</div>${media}<p class="surprise-text">${esc(n.body||'💕')}</p>${n.mode==='reply'?`<input class="surprise-reply" maxlength="150" placeholder="${esc(visitorTranslations?.[p.lang]?.surpriseAnswer||(surpriseUI[p.lang]||surpriseUI.en)[1])}"/>`:''}<button type="button" id="preview-surprise-next" class="primary-btn">${esc(n.button_label||'Continue 💕')}</button>`);
  }
  el.innerHTML=`<div class="preview-dialog"><header class="preview-toolbar"><div><strong>◉ TEST MODE</strong><small>No records, notifications or real invitations are created.</small></div><div class="preview-toolbar-actions"><button type="button" class="mini-btn" id="preview-mobile">Mobile</button><button type="button" class="mini-btn" id="preview-desktop">Desktop</button><button type="button" class="mini-btn" id="preview-close" aria-label="Close preview">✕</button></div></header><div class="preview-scroll"><div class="preview-device ${p.device==='mobile'?'preview-mobile':'preview-desktop'}"><div class="preview-brand">${brand}</div>${content}<div class="preview-footer">DateWith${esc(ownerName)} ♡ · ${esc(localeNames[p.lang]||p.lang)}</div></div></div><footer class="preview-controls"><button type="button" id="preview-back" class="mini-btn" ${p.position===0?'disabled':''}>← Previous</button><span>${p.position+1} / ${p.steps.length}</span><button type="button" id="preview-next" class="primary-btn">${p.position===p.steps.length-1?'Restart':'Next →'}</button></footer></div>`;
  el.querySelector('#preview-close').onclick=closeInvitePreview;
  el.querySelector('#preview-mobile').onclick=()=>{p.device='mobile';renderInvitePreview()};
  el.querySelector('#preview-desktop').onclick=()=>{p.device='desktop';renderInvitePreview()};
  el.querySelector('#preview-back').onclick=()=>{p.position=Math.max(0,p.position-1);renderInvitePreview()};
  const advance=()=>{p.position=(p.position+1)%p.steps.length;renderInvitePreview()};
  el.querySelector('#preview-next').onclick=advance;
  el.querySelector('#preview-yes')?.addEventListener('click',advance);
  el.querySelector('#preview-book')?.addEventListener('click',advance);
  el.querySelector('#preview-surprise-next')?.addEventListener('click',advance);
  el.querySelector('#preview-no')?.addEventListener('pointerenter',()=>{
    if(!el.querySelector('#preview-no')?.isConnected)return;
    el.querySelector('#preview-no').style.transform='translate(60px, -42px)';
    setTimeout(()=>{const btn=el.querySelector('#preview-no');if(btn)btn.style.transform=''},260);
  });
  el.querySelector('#preview-no')?.addEventListener('click',()=>toast('This is only a preview. The No button escaped! 😄'));
  el.querySelector('#preview-day')?.addEventListener('change',e=>p.day=e.target.value);
  el.querySelector('#preview-time')?.addEventListener('change',e=>p.time=e.target.value);
  el.querySelectorAll('[data-preview-activity]').forEach(b=>b.onclick=()=>{p.activity=p.deck.cards.find(c=>c.id===b.dataset.previewActivity);advance()});
}
function adminLocalization(){
  const lang=localeEditLanguage,scope=localeEditScope;
  const visitorKeys=[...keys,'selectLanguage','appleCalendar','googleCalendar','outlookCalendar','surpriseTitle','surpriseAnswer','postDateNote'];
  const adminKeys=[...new Set([...Object.keys(panelDictionary.en),...Object.keys(panelDictionary.ru),...adminBaseLabels,'Create a new invitation','Sent Invitations','Saved People','Scheduling Settings','Backup and Settings Transfer','Save','Preview','Surprise Messages','Preview as Invitee (Test)','Post-date surprise (on each visit)'])];
  const terms=scope==='visitor'?visitorKeys:adminKeys;
  const custom=admin.ui_overrides?.[scope]?.[lang]||{};
  const defaults=scope==='visitor'?{...(LOCALES[lang]||LOCALES.en),...Object.fromEntries(Object.keys(publicUi).map(k=>[k,publicUi[k]?.[lang]||publicUi[k]?.en])),surpriseTitle:(surpriseUI[lang]||surpriseUI.en)[0],surpriseAnswer:(surpriseUI[lang]||surpriseUI.en)[1]}:panelDictionary[lang]||{};
  return panelCard('Localization Editor',`<p>Customize interface text in 16 languages. Unspecified fields use the built-in translations. Your changes are stored only in this installation.</p><div class="form-grid"><div class="field"><label>Section</label><select id="locale-edit-scope"><option value="visitor" ${scope==='visitor'?'selected':''}>Visitor interface</option><option value="admin" ${scope==='admin'?'selected':''}>Admin panel</option></select></div><div class="field"><label>Language</label><select id="locale-edit-language">${Object.entries(localeNames).map(([c,n])=>`<option value="${c}" ${lang===c?'selected':''}>${esc(n)}</option>`).join('')}</select></div></div><form id="locale-edit-form"><div class="locale-editor-grid">${terms.map(key=>`<div class="field locale-editor-entry"><label>${esc(scope==='visitor'?(LOCALES.en[key]||publicUi[key]?.en||(key==='surpriseTitle'?surpriseUI.en[0]:key==='surpriseAnswer'?surpriseUI.en[1]:key)):key)}</label><input data-locale-key="${esc(key)}" maxlength="400" value="${esc(custom[key]||'')}" placeholder="${esc(defaults[key]||panelDictionary.en[key]||key)}" /></div>`).join('')}</div><div class="form-actions"><button class="primary-btn" type="submit">Save Translations</button></div></form>`);
}

