    sortArea.addEventListener('dragover',e=>{if(!dragCardSlug)return;e.preventDefault();const over=e.target.closest('[data-sort-card]');if(!over || over.dataset.sortCard===dragCardSlug)return;const drag=sortArea.querySelector('.dragging');if(!drag)return;const box=over.getBoundingClientRect();sortArea.insertBefore(drag,e.clientY<box.top+box.height/2?over:over.nextSibling)});
