      handle.addEventListener('pointermove',e=>{if(!active||!from)return;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-sort-card]');if(!target||target===from||!sortArea.contains(target))return;const rect=target.getBoundingClientRect();sortArea.insertBefore(from,e.clientY<rect.top+rect.height/2?target:target.nextSibling)});
